public class FitnessFunction_encode_TriageGen0Test {

    @Test
    public void testEncode_BoundariesIsNull() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        double[] x = {1.0, 2.0, 3.0};

        // The default state of boundaries is null based on the provided logic
        double[] result = fitnessFunction.encode(x);

        Assert.assertArrayEquals(x, result, 1e-9);
    }

    @Test
    public void testEncode_NormalOperation() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        // Use reflection to set the private 'boundaries' field for testing
        // boundaries is expected to be double[2][dimension]
        double[][] boundaries = {
            {0.0, 10.0, -5.0}, // lower bounds (boundaries[0])
            {10.0, 20.0, 5.0}  // upper bounds (boundaries[1])
        };

        setPrivateField(fitnessFunction, "boundaries", boundaries);

        double[] x = {5.0, 15.0, 0.0};
        // Expected calculation:
        // i=0: (5.0 - 0.0) / (10.0 - 0.0) = 0.5
        // i=1: (15.0 - 10.0) / (20.0 - 10.0) = 0.5
        // i=2: (0.0 - (-5.0)) / (5.0 - (-5.0)) = 5.0 / 10.0 = 0.5
        double[] expected = {0.5, 0.5, 0.5};

        double[] result = fitnessFunction.encode(x);

        Assert.assertArrayEquals(expected, result, 1e-9);
    }

    @Test
    public void testEncode_SingleElement() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        double[][] boundaries = {
            {0.0},
            {100.0}
        };
        setPrivateField(fitnessFunction, "boundaries", boundaries);

        double[] x = {25.0};
        double[] expected = {0.25};

        double[] result = fitnessFunction.encode(x);

        Assert.assertArrayEquals(expected, result, 1e-9);
    }

    /**
     * Helper method to inject the boundaries field via reflection since it is likely private.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
